import json, re, statistics

with open('$RESULTS_FILE') as f:
    raw = json.load(f)

data = json.loads(raw['result'])
experiments = data['data']['experiments']

norm_results = {}
for eid, exp in experiments.items():
    conclusion = exp.get('conclusion', '')
    if conclusion not in ('success', 'negative'):
        continue
    metrics = exp.get('metrics', {})
    sr = metrics.get('overall_success_rate')
    if sr is None:
        continue

    # Determine epsilon from exp_id or command
    eps = None
    if 'norm003' in eid:
        eps = 0.03
    elif 'norm005' in eid:
        eps = 0.05
    elif 'norm01' in eid and 'norm02' not in eid:
        eps = 0.1
    elif 'norm02' in eid:
        eps = 0.2
    else:
        # Check command for --max_correction_norm
        spec = exp.get('spec', {})
        cmd = spec.get('command', '')
        norm_match = re.search(r'--max_correction_norm\s+([\d.]+)', cmd)
        if norm_match:
            eps = float(norm_match.group(1))

    if eps is None:
        continue

    # Must be obs_only mode
    if 'obs-only' not in eid and 'obs_only' not in eid:
        spec = exp.get('spec', {})
        cmd = spec.get('command', '')
        if 'crm_obs_only' not in cmd:
            continue

    seed_match = re.search(r'seed(\d+)', eid)
    if not seed_match:
        continue
    seed = int(seed_match.group(1))

    if eps not in norm_results:
        norm_results[eps] = {}
    if seed not in norm_results[eps] or sr > norm_results[eps][seed]['sr']:
        norm_results[eps][seed] = {'sr': sr, 'exp_id': eid}

print('=== Norm Sweep Complete Statistics ===')
print()
for eps in sorted(norm_results.keys()):
    entries = norm_results[eps]
    srs = [e['sr'] for e in entries.values()]
    mean_sr = statistics.mean(srs)
    std_sr = statistics.stdev(srs) if len(srs) > 1 else 0
    seeds_str = ', '.join([f's{s}={entries[s][\"sr\"]:.0%}' for s in sorted(entries.keys())])
    print(f'ε={eps}: n={len(srs)}, mean={mean_sr:.1%}±{std_sr:.1%}')
    print(f'  Seeds: {seeds_str}')
    print()

print('=== RUNNING experiments ===')
for eid, exp in experiments.items():
    if exp.get('conclusion') is None and 'obs-only' in eid:
        spec = exp.get('spec', {})
        server = spec.get('server', '?')
        gpu = spec.get('gpu', '?')
        print(f'{eid}: server={server}, gpu={gpu}')
